import React, { createContext, useState } from 'react';
import axios from 'axios';

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
    const [users, setUsers] = useState([]);

    const validationPatterns = {
        usuario: /^[a-z][a-z0-9]{5,}$/, // Mínimo 6 caracteres, comienza con letra minúscula
        contra: /^(?=.*[A-Z])(?=.*\d)[A-Za-z\d]{8,}$/, // Mínimo 8 caracteres, al menos una mayúscula y un número
    };

    const addUser = (newUser) => {
        setUsers([...users, newUser]);
    };

    const deleteUser = async (usuario) => {
        try {
            // Realizamos la solicitud DELETE al backend para eliminar el usuario, ahora con el campo usuario
            const response = await axios.delete('http://localhost/SERVIDOR/practica/delete_user.php', {
                data: { usuario: usuario }  // Enviamos el nombre del usuario en el cuerpo de la solicitud
            });

            if (response.data.success) {
                // Si la eliminación es exitosa en el servidor, actualizamos el estado local
                setUsers(users.filter(user => user.usuario !== usuario)); // Filtramos por nombre de usuario
            } else {
                alert('Error al eliminar el usuario: ' + response.data.message);
            }
        } catch (error) {
            console.error('Error al eliminar el usuario:', error);
            alert('Hubo un error al eliminar el usuario.');
        }
    };

    return (
        <UserContext.Provider value={{ users, addUser, deleteUser, validationPatterns }}>
            {children}
        </UserContext.Provider>
    );
};
